from math import comb
from itertools import combinations

def allowed_pairs(names, limit):
    count = comb(len(names), 2)
    if count > limit:
        raise ValueError('too many review pairs')
    return list(combinations(names, 2))

assert allowed_pairs(['Ada', 'Bo', 'Cy'], 3) == [
    ('Ada', 'Bo'), ('Ada', 'Cy'), ('Bo', 'Cy')]
try:
    allowed_pairs(['a', 'b', 'c', 'd', 'e'], 3)
except ValueError:
    pass
else:
    raise AssertionError('large request accepted')
print('pair budget checked')
